<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';import {useRoute} from 'vue-router';
import {extraMessage,type SystemMessage} from '../lib/messages';import MessageIcon from './MessageIcon.vue';
const route=useRoute(),messages=ref<SystemMessage[]>([]),open=ref(false),bar=ref<HTMLElement>(),popup=ref<HTMLElement>(),trigger=ref<HTMLButtonElement>(),pageTitle=ref('当前页面');let observer:MutationObserver|undefined,resize:ResizeObserver|undefined,frame=0,fingerprint='';
function sync(){frame=0;pageTitle.value=document.querySelector('.page h1,.login-panel h2')?.textContent?.trim()||'当前页面';const list:SystemMessage[]=[];for(const node of document.querySelectorAll<HTMLElement>('.alert.error,.alert.warning,.alert.success,.text-danger[role="alert"]')){if(node.closest('.app-status-bar,.message-details')||!node.getClientRects().length)continue;const kind=node.classList.contains('warning')?'W':node.classList.contains('success')?'S':'E',entries=node.matches('.alert.error')&&node.querySelector('li')?Array.from(node.querySelectorAll<HTMLElement>('li')):[node];for(const entry of entries){const text=(entry.dataset.message??entry.textContent)?.trim().replace(/\s+/g,' ');if(text&&!list.some(m=>entry.dataset.messageId?m.source?.dataset.messageId===entry.dataset.messageId:m.kind===kind&&m.text===text))list.push({kind,text,source:entry});}}
 list.sort((a,b)=>'EWSI'.indexOf(a.kind)-'EWSI'.indexOf(b.kind));const key=JSON.stringify(list.map(({kind,text})=>({kind,text})));if(key!==fingerprint||list.some((m,i)=>m.source!==messages.value[i]?.source)){fingerprint=key;messages.value=list;}}
function schedule(){if(!frame)frame=requestAnimationFrame(sync);}
function corrected(event:Event){if(extraMessage.value?.source===event.target&&(event.target as HTMLInputElement).validity?.valid)extraMessage.value=null;}
function invalid(event:Event){const input=event.target as HTMLInputElement;if(input.matches('input,select,textarea')){const label=input.labels?.[0]?.querySelector('.field-caption')?.textContent??input.getAttribute('aria-label')??'字段';extraMessage.value={kind:'E',text:label+'：'+input.validationMessage,source:input};}}
const all=computed(()=>[...messages.value,...(extraMessage.value?[extraMessage.value]:[])].sort((a,b)=>'EWSI'.indexOf(a.kind)-'EWSI'.indexOf(b.kind))),errors=computed(()=>all.value.filter(m=>m.kind==='E').length),warnings=computed(()=>all.value.filter(m=>m.kind==='W').length),current=computed(()=>all.value[0]),kind=computed(()=>current.value?.kind??'I');
const summary=computed(()=>`系统消息：${errors.value} 个错误，${warnings.value} 个警告，共 ${all.value.length} 条；点击查看`);
function field(message:SystemMessage){return message.source?.closest('label')?.querySelector('.field-caption')?.textContent?.trim()||(message.text.includes('：')?message.text.split('：')[0]:pageTitle.value);}
function close(restore=true){open.value=false;if(restore)trigger.value?.focus();}
function focus(message:SystemMessage){close(false);void nextTick(()=>{const node=message.source;if(!node?.isConnected)return;const anchor=node.querySelector<HTMLAnchorElement>('a[href="#"]');if(anchor){anchor.click();return;}const target=node.matches('input,select,textarea')?node:node.querySelector<HTMLElement>('input,select,textarea')??node;target.scrollIntoView({block:'center'});if(!target.hasAttribute('tabindex')&&!target.matches('input,select,textarea'))target.setAttribute('tabindex','-1');target.focus();});}
function outside(event:Event){if(open.value&&!popup.value?.contains(event.target as Node)&&!trigger.value?.contains(event.target as Node))close(false);}
function keyboard(event:KeyboardEvent){if(open.value&&event.key==='Escape'){event.preventDefault();close();}}
function size(){const height=Math.ceil(bar.value?.getBoundingClientRect().height??56)+24;document.documentElement.style.setProperty('--footer-height',height+'px');}
watch(open,async value=>{if(value){await nextTick();popup.value?.querySelector<HTMLButtonElement>('.message-close')?.focus();}});
watch(()=>route.fullPath,()=>{extraMessage.value=null;open.value=false;fingerprint='';schedule();});
onMounted(()=>{observer=new MutationObserver(schedule);observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['class','aria-invalid','open','hidden']});resize=new ResizeObserver(size);if(bar.value)resize.observe(bar.value);size();document.addEventListener('invalid',invalid,true);document.addEventListener('input',corrected,true);document.addEventListener('pointerdown',outside);document.addEventListener('keydown',keyboard);sync();});onBeforeUnmount(()=>{observer?.disconnect();resize?.disconnect();cancelAnimationFrame(frame);document.removeEventListener('invalid',invalid,true);document.removeEventListener('input',corrected,true);document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',keyboard);document.documentElement.style.removeProperty('--footer-height');});
</script>
<template>
 <footer ref="bar" class="app-status-bar" :class="{'with-sidebar':route.path!=='/login'}" aria-label="页面状态与操作">
  <aside class="message-area" aria-label="系统消息"><button ref="trigger" type="button" class="message-summary" :class="'message-'+kind" :aria-expanded="open" aria-controls="system-message-list" aria-haspopup="dialog" :aria-label="summary" :title="summary" @click="open=!open"><span class="message-symbol" aria-hidden="true"><MessageIcon :kind="kind"/></span><span>{{ all.length }}</span></button><span class="sr-only" role="status" aria-live="polite" aria-atomic="true">{{ current?.kind==='E'?'错误':current?.kind==='W'?'警告':'提示' }} {{ current?.text }}</span></aside>
  <div id="page-actions" aria-label="页面操作"></div>
  <section v-if="open" id="system-message-list" ref="popup" class="message-details message-popover" role="dialog" aria-label="系统消息"><header><h2>系统消息</h2><button type="button" class="message-close" aria-label="关闭系统消息" @click="close()">×</button></header><h3>{{ pageTitle }} <small v-if="errors||warnings">错误 {{ errors }} · 警告 {{ warnings }}</small></h3><div class="message-list"><p v-if="!all.length" class="message-empty">当前没有错误或警告。提交时会检查必填项。</p><article v-for="(message,index) in all" :key="index"><button type="button" class="message-row" :disabled="!message.source?.isConnected" @click="focus(message)"><span class="message-code" :class="'message-'+message.kind"><MessageIcon :kind="message.kind"/></span><span class="message-text"><strong>{{ message.text }}</strong><small>{{ field(message) }}</small></span><span class="message-chevron" aria-hidden="true">›</span></button></article></div></section>
 </footer>
</template>
<style scoped>
.app-status-bar{position:fixed;left:12px;right:12px;bottom:max(12px,env(safe-area-inset-bottom));display:flex;align-items:center;gap:16px;min-height:56px;padding:8px 12px;background:var(--paper);border:1px solid #a7afb7;border-radius:10px;box-shadow:0 2px 10px #29384626;z-index:35;max-height:40dvh}.message-area{flex-shrink:0;align-self:flex-end}.message-summary{display:flex;align-items:center;justify-content:center;gap:7px;min-height:36px;min-width:56px;padding:5px 10px;border:0;border-radius:8px;font-size:14px;font-weight:600}.message-summary.message-E{color:white;background:#e3343b}.message-summary.message-W{color:#755300;background:#ffe6a0}.message-summary.message-S,.message-summary.message-I{color:white;background:#0868c9}.message-symbol{display:grid;place-items:center}.message-symbol :deep(.message-icon){width:20px;height:20px}.message-summary.message-E :deep(.shape),.message-summary.message-S :deep(.shape),.message-summary.message-I :deep(.shape){fill:white}.message-summary.message-E :deep(.mark){stroke:#e3343b}.message-summary.message-S :deep(.mark),.message-summary.message-I :deep(.mark){stroke:#0868c9}#page-actions{flex:1;min-width:0;overflow-y:auto;max-height:calc(40dvh - 16px)}.message-popover{position:fixed;bottom:var(--footer-height,80px);left:12px;width:min(480px,calc(100vw - 24px));max-height:min(65dvh,600px);display:flex;flex-direction:column;background:var(--paper);border:1px solid #8a969f;border-radius:12px;box-shadow:0 8px 28px #29384633;overflow:hidden;color:var(--ink)}.message-popover header{display:flex;justify-content:space-between;align-items:center;padding:12px 18px;border-bottom:1px solid #ccd3d8}.message-popover h2{font-size:17px;margin:0}.message-close{border:0;background:transparent;color:#0868c9;font-size:25px;line-height:1;padding:4px 10px;min-height:36px}.message-popover h3{font-size:15px;margin:0;padding:12px 18px;border-bottom:1px solid #ccd3d8}.message-popover h3 small{display:inline;margin-left:10px;font-size:12px;font-weight:400}.message-list{overflow:auto;min-height:0}.message-row{width:100%;display:flex;align-items:center;gap:14px;text-align:left;border:0;border-radius:0;border-bottom:1px solid #dce0e3;background:transparent;white-space:normal;padding:14px 18px}.message-row:hover{background:#e9f2fc}.message-text{min-width:0;flex:1}.message-text strong{display:block;font-size:14px;font-weight:500;line-height:1.6;color:#0868c9;overflow-wrap:anywhere}.message-text small{font-size:13px;color:#516b82;margin-top:3px}.message-code{display:grid;place-items:center;flex-shrink:0;width:24px;height:24px}.message-chevron{font-size:25px;color:#7c96ae}.message-empty{padding:20px;font-size:14px;margin:0}@media(min-width:761px){.app-status-bar.with-sidebar{left:240px}.app-status-bar.with-sidebar .message-popover{left:240px;width:min(480px,calc(100vw - 252px))}}@media(max-width:760px){.app-status-bar{left:8px;right:8px;bottom:max(8px,env(safe-area-inset-bottom));padding:6px 8px;gap:8px}.message-summary{min-height:44px;min-width:48px;padding:4px 8px}.message-popover{left:8px;width:calc(100vw - 16px)}.message-row{padding:12px;gap:10px}}@media print{.app-status-bar{display:none}}
/* Keep blur on a separate background so the fixed message popup stays viewport-anchored. */
@supports ((backdrop-filter:blur(10px)) or (-webkit-backdrop-filter:blur(10px))){
 .app-status-bar{background:transparent}
 .app-status-bar::before{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:rgba(255,253,249,.85);background:color-mix(in srgb,var(--paper) 85%,transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);pointer-events:none}
}
</style>
